                        fontSize = 12.sp
                    )
                    Text(
                        text = "Constraint: $min - $max",
                        color = Color.DarkGray,
                        fontSize = 10.sp
                    )
                }

                Button(
                    onClick = {
                        if (canSubmit && pendingId == null && !isPersisting) {
                            val qualityCheck = ValidationUtils.isContentLowQuality(userText)
