@Composable
private fun RewardDistributionRow(
    place: String,
    merit: String,
    percent: String,
    participant: String,
    onClick: () -> Unit
) {
    val placeColor = when (place) {
        "1st" -> MaterialTheme.colorScheme.primary
        "2nd" -> Color.LightGray
        "3rd" -> Color(0xFFCD7F32)
        else -> Color.Gray
    }

    Row(
        modifier = Modifier
            .fillMaxWidth()
            .clip(RoundedCornerShape(10.dp))
            .clickable(onClick = onClick)
            .padding(vertical = 10.dp, horizontal = 4.dp),
        verticalAlignment = Alignment.CenterVertically
    ) {
        Text(
            text = place,
            modifier = Modifier.width(45.dp),
            color = placeColor,
            fontWeight = FontWeight.Black,
            fontSize = 13.sp
        )

        Text(
            text = merit,
            modifier = Modifier.width(75.dp),
            color = Color.White,
            fontWeight = FontWeight.Bold,
            fontSize = 13.sp
        )

        Text(
            text = percent,
            modifier = Modifier.width(65.dp),
            color = Color.Gray,
            fontSize = 13.sp
        )

        Text(
            text = participant,
            modifier = Modifier.weight(1f),
            color = if (participant == "TBD") Color.DarkGray else Color.White,
            fontSize = 13.sp,
            fontWeight = if (participant == "TBD") FontWeight.Normal else FontWeight.Bold,
            maxLines = 1
        )
    }
}

