package com.inkr8.utils

import java.text.SimpleDateFormat
import java.util.Date
import java.util.Locale
import java.util.concurrent.TimeUnit

object TimeUtils {

    fun formatTime(timestamp: Long): String {
        val now = System.currentTimeMillis()
        val diff = now - timestamp

        return when {
            diff < TimeUnit.MINUTES.toMillis(1) -> "just now"
            diff < TimeUnit.HOURS.toMillis(1) -> {
                val minutes = TimeUnit.MILLISECONDS.toMinutes(diff)
                if(minutes.toInt() == 1){
                    "${minutes} minute ago"
                }else{
                    "${minutes} minutes ago"
                }

            }
            diff < TimeUnit.DAYS.toMillis(1) -> {
                val hours = TimeUnit.MILLISECONDS.toHours(diff)
                if(hours.toInt() == 1){
                    "${hours} hour ago"
                }else{
                    "${hours} hours ago"
                }
            }
            diff < TimeUnit.DAYS.toMillis(30) -> {
                val days = TimeUnit.MILLISECONDS.toDays(diff)
                if(days.toInt() == 1){
                    "${days} day ago"
                }else{
                    "${days} days ago"
                }
            }
            diff < TimeUnit.DAYS.toMillis(365) -> {
                val months = TimeUnit.MILLISECONDS.toDays(diff) / 30
                if(months.toInt() == 1){
                    "${months} month ago"
                }else{
                    "${months} months ago"
                }
            }
            else -> {
                val years = TimeUnit.MILLISECONDS.toDays(diff) / 365
                if(years.toInt() == 1){
                    "${years} year ago"
                }else{
                    "${years} years ago"
                }
            }
        }
    }

    fun formatDate(timestamp: Long): String {
        val date = SimpleDateFormat("MMM dd, yyyy", Locale.getDefault())
        return date.format(Date(timestamp))
    }

    // specifically for tournaments :-)
    fun formatRemainingTime(targetTimestamp: Long): String {
        val diff = targetTimestamp - System.currentTimeMillis()

        if (diff <= 0L) return "Ended"

        val totalSeconds = diff / 1000
        val days = totalSeconds / 86400
        val hours = (totalSeconds % 86400) / 3600
        val minutes = (totalSeconds % 3600) / 60

        return when {
            days > 0 -> "${days}d ${hours}h"
            hours > 0 -> "${hours}h ${minutes}m"
            else -> "${minutes}m"
        }
    }
}

