import {onSchedule} from "firebase-functions/v2/scheduler";
import {db, FieldValue} from "../firebase/admin";
import {getLeagueFromRating} from "../utils/leagueManager";

export const ghostMatchProcessor = onSchedule(
  {
    schedule: "every 1 hours",
    region: "us-central1",
  },
  async () => {
    const FORTY_EIGHT_HOURS_MS = 48 * 60 * 60 * 1000;
    const cutoff = Date.now() - FORTY_EIGHT_HOURS_MS;

    // find ranked submissions still PENDING older than 48 hours
    const pendingSnap = await db.collection("submissions")
      .where("playmode", "==", "RANKED")
      .where("status", "==", "EVALUATED")
      .where("matchStatus", "==", "PENDING")
      .where("timestamp", "<=", cutoff)
      .limit(50)
      .get();

    if (pendingSnap.empty) return;

    const BENCHMARK_SCORE = 65.0;

    for (const doc of pendingSnap.docs) {
      const data = doc.data();
      const authorId = data.authorId;
      const myScore = Number(data.evaluation?.finalScore ?? 0);

      const userRef = db.collection("users").doc(authorId);
      await db.runTransaction(async (tx) => {
        const currentSubmission = await tx.get(doc.ref);
        if (currentSubmission.get("status") !== "EVALUATED" ||
            currentSubmission.get("matchStatus") !== "PENDING") return;
        const userSnap = await tx.get(userRef);
        if (!userSnap.exists) return;

        const userData = userSnap.data() ?? {};
        const recentScores: number[] = Array.isArray(userData.recentScores) ? userData.recentScores : [];
        const isPlaced = userData.isPlaced === true;

        let ghostRatingChange = 0;
        let outcome = "DRAW";
        let opponentScore = BENCHMARK_SCORE;

        if (recentScores.length >= 3) {
          opponentScore = recentScores.slice(-10).reduce((a, b) => a + b, 0) / Math.min(recentScores.length, 10);
        }

        if (myScore > opponentScore + 2) {
          ghostRatingChange = 2;
          outcome = "WIN";
        } else if (myScore < opponentScore - 2) {
          ghostRatingChange = -4;
          outcome = "LOSS";
        } else {
          ghostRatingChange = 1;
          outcome = "DRAW";
        }

        const currentRating = Number(userData.rating ?? 0);

        tx.update(doc.ref, {
          "matchStatus": "GHOST",
          "matchResult": {
            opponentId: "GHOST",
            opponentName: "R8 Average",
            opponentScore: opponentScore,
            outcome,
            ratingChange: ghostRatingChange,
          },
          "evaluation.ratingChange": ghostRatingChange,
        });

        if (isPlaced) {
          const newRating = Math.max(0, currentRating + ghostRatingChange);
          tx.update(userRef, {
            rating: newRating,
          });

          if (authorId !== "R8") {
            const oldLeague = getLeagueFromRating(currentRating);
            const newLeague = getLeagueFromRating(newRating);

            if (oldLeague !== newLeague) {
              const statsRef = db.collection("metadata").doc("rankings");
              tx.set(statsRef, {
                leagueCounts: {
                  [oldLeague]: FieldValue.increment(-1),
                  [newLeague]: FieldValue.increment(1),
                },
              }, {merge: true});
            }
          }
        }
      });
    }
  }
);

functions/src/submissions/rankedMatching.before_text:
import {db, FieldValue} from "../firebase/admin";
import {getLeagueFromRating} from "../utils/leagueManager";
import {calculateDynamicRatingChange} from "../utils/dynamicRatingChange";

export async function tryMatchRankedSubmission(
  submissionId: string,
  authorId: string,
  authorScore: number,
  authorRating: number,
  authorName: string
): Promise<void> {
  const RATING_RANGE = 20;
  const FORTY_EIGHT_HOURS_MS = 48 * 60 * 60 * 1000;
  const since = Date.now() - FORTY_EIGHT_HOURS_MS;

  const candidatesSnap = await db.collection("submissions")
    .where("playmode", "==", "RANKED")
    .where("status", "==", "EVALUATED")
    .where("matchStatus", "==", "PENDING")
    .where("timestamp", ">=", since)
    .get();

  const submitterRef = db.collection("users").doc(authorId);
  const mySubmissionRef = db.collection("submissions").doc(submissionId);

  for (const doc of candidatesSnap.docs) {
    const candidate = doc.data();

    if (candidate.authorId === authorId) continue;

    const candidateUserSnap = await db.collection("users").doc(candidate.authorId).get();
    if (!candidateUserSnap.exists) continue;
    const candidateRating = Number(candidateUserSnap.data()?.rating ?? 0);

    if (Math.abs(authorRating - candidateRating) > RATING_RANGE) continue;

    const candidateScore = Number(candidate.evaluation?.finalScore ?? 0);
    const candidateRef = doc.ref;
    const candidateAuthorRef = db.collection("users").doc(candidate.authorId);

    const myScoreWins = authorScore > candidateScore;
    const isDraw = authorScore === candidateScore;

    const candidateName = candidateUserSnap.data()?.name ?? "Unknown";

    const leagueAdjustments = await db.runTransaction(async (tx) => {
      const mySubmissionSnap = await tx.get(mySubmissionRef);
      const candidateSubmissionSnap = await tx.get(candidateRef);
      if (mySubmissionSnap.get("status") !== "EVALUATED" ||
          mySubmissionSnap.get("matchStatus") !== "PENDING" ||
          candidateSubmissionSnap.get("status") !== "EVALUATED" ||
          candidateSubmissionSnap.get("matchStatus") !== "PENDING") return null;

      const leagueAdjustments: Record<string, number> = {};
      const submitterSnap = await tx.get(submitterRef);
      const candidateUserSnapTx = await tx.get(candidateAuthorRef);

      if (!submitterSnap.exists || !candidateUserSnapTx.exists) return null;

      const submitterData = submitterSnap.data();
      const candidateData = candidateUserSnapTx.data();

      const currentMyRating = Number(submitterData?.rating ?? 0);
      const currentTheirRating = Number(candidateData?.rating ?? 0);
      const myIsPlaced = submitterData?.isPlaced === true;
      const candidateIsPlaced = candidateData?.isPlaced === true;

      const myRatingChange = calculateDynamicRatingChange(
        currentMyRating,
        currentTheirRating,
        isDraw ? "DRAW" : myScoreWins ? "WIN" : "LOSS"
      );

      const theirRatingChange = calculateDynamicRatingChange(
        currentTheirRating,
        currentMyRating,
        isDraw ? "DRAW" : myScoreWins ? "LOSS" : "WIN"
      );

      tx.update(mySubmissionRef, {
        "matchStatus": "MATCHED",
        "matchResult": {
          opponentId: candidate.authorId,
          opponentName: candidateName,
          opponentScore: candidateScore,
          outcome: isDraw ? "DRAW" : myScoreWins ? "WIN" : "LOSS",
          ratingChange: myRatingChange,
        },
        "evaluation.ratingChange": myRatingChange,
      });

      tx.update(candidateRef, {
        "matchStatus": "MATCHED",
        "matchResult": {
          opponentId: authorId,
          opponentName: authorName,
          opponentScore: authorScore,
          outcome: isDraw ? "DRAW" : myScoreWins ? "LOSS" : "WIN",
          ratingChange: theirRatingChange,
        },
        "evaluation.ratingChange": theirRatingChange,
      });

      if (myIsPlaced) {
        const newRating = Math.max(0, currentMyRating + myRatingChange);
        const myOutcome = isDraw ? "DRAW" : myScoreWins ? "WIN" : "LOSS";
        const myWinStreak = Number(submitterData?.rankedWinStreak ?? 0);
        const myLossStreak = Number(submitterData?.rankedLossStreak ?? 0);

        const newMyWinStreak = myOutcome === "WIN" ? myWinStreak + 1 : 0;
        const newMyLossStreak = myOutcome === "LOSS" ? myLossStreak + 1 : 0;

        tx.update(submitterRef, {
          rating: newRating,
          rankedWinStreak: newMyWinStreak,
          rankedLossStreak: newMyLossStreak,
        });

        if (authorId !== "R8") {
          const oldLeague = getLeagueFromRating(currentMyRating);
          const newLeague = getLeagueFromRating(newRating);
          if (oldLeague !== newLeague) {
            leagueAdjustments[oldLeague] = (leagueAdjustments[oldLeague] || 0) - 1;
            leagueAdjustments[newLeague] = (leagueAdjustments[newLeague] || 0) + 1;
          }
        }
      }

      if (candidateIsPlaced) {
        const newRating = Math.max(0, currentTheirRating + theirRatingChange);
        const theirOutcome = isDraw ? "DRAW" : myScoreWins ? "LOSS" : "WIN";
        const theirWinStreak = Number(candidateData?.rankedWinStreak ?? 0);
        const theirLossStreak = Number(candidateData?.rankedLossStreak ?? 0);

        const newTheirWinStreak = theirOutcome === "WIN" ? theirWinStreak + 1 : 0;
        const newTheirLossStreak = theirOutcome === "LOSS" ? theirLossStreak + 1 : 0;

        tx.update(candidateAuthorRef, {
          rating: newRating,
          rankedWinStreak: newTheirWinStreak,
          rankedLossStreak: newTheirLossStreak,
        });

        if (candidate.authorId !== "R8") {
          const oldLeague = getLeagueFromRating(currentTheirRating);
          const newLeague = getLeagueFromRating(newRating);
          if (oldLeague !== newLeague) {
            leagueAdjustments[oldLeague] = (leagueAdjustments[oldLeague] || 0) - 1;
            leagueAdjustments[newLeague] = (leagueAdjustments[newLeague] || 0) + 1;
          }
        }
      }
      return leagueAdjustments;
    });
    if (leagueAdjustments === null) continue;

    // Optimization: Update global stats outside the transaction
    if (Object.keys(leagueAdjustments).length > 0) {
      const statsUpdate: Record<string, unknown> = {};
      Object.entries(leagueAdjustments).forEach(([league, increment]) => {
        statsUpdate[`leagueCounts.${league}`] = FieldValue.increment(increment);
      });
      db.collection("metadata").doc("rankings").update(statsUpdate)
        .catch((err) => console.error("Match-driven global stats update failed:", err));
    }

    return;
  }

  // The evaluation transaction already queued this submission. Do not reset a concurrent match.
}

functions/src/submissions/submissionEval.before_text:
import {onDocumentCreated} from "firebase-functions/v2/firestore";
import {db, FieldValue} from "../firebase/admin";
import {OPENAI_API_KEY, evaluateWithR8} from "../r8/evaluateWithR8";
import {calculateMerit} from "../utils/meritCalculator";
import {onRankedCompleted} from "../utils/reputationManager";
import {pruneOldSubmissions} from "./pruneOldSubmissions";
import {getLeagueFromRating} from "../utils/leagueManager";
import {tryMatchRankedSubmission} from "./rankedMatching";

function getUtcDayInt(): number {
  const now = new Date();
  return now.getUTCFullYear() * 10000 + (now.getUTCMonth() + 1) * 100 + now.getUTCDate();
}

function getStreakMultiplier(streak: number): number {
  if (streak >= 7) return 1.12;
  if (streak >= 6) return 1.10;
  if (streak >= 5) return 1.08;
  if (streak >= 4) return 1.06;
  if (streak >= 3) return 1.05;
  if (streak >= 2) return 1.03;
  return 1.0;
}

// quality check to filter out nonsense or highly repetitive content >:(
function isContentLowQuality(content: string): { isLowQuality: boolean; reason?: string } {
  const trimmed = content.trim();
  if (trimmed.length < 50) return {isLowQuality: true, reason: "Content too short (min 50 chars)"};

  const words = trimmed.split(/\s+/).filter((w) => w.length > 0);

  if (words.some((w) => w.length > 35)) {
    return {isLowQuality: true, reason: "Nonsense detected (excessive word length)"};
  }

  if (words.length >= 10) {
    const uniqueWords = new Set(words.map((w) => w.toLowerCase()));
    if (uniqueWords.size / words.length < 0.35) {
      return {isLowQuality: true, reason: "Repetitive content detected"};
    }
  }

  const letters = trimmed.replace(/[^a-zA-Z]/g, "");
  if (letters.length > 30) {
    const vowels = letters.match(/[aeiouAEIOU]/g) || [];
    const vowelRatio = vowels.length / letters.length;
    if (vowelRatio < 0.15 || vowelRatio > 0.8) {
      return {isLowQuality: true, reason: "Unnatural character distribution (nonsense)"};
    }

    const uniqueLetters = new Set(letters.toLowerCase().split(""));
    if (uniqueLetters.size < 8 && letters.length > 60) {
      return {isLowQuality: true, reason: "Low character diversity (nonsense)"};
    }
  }

  return {isLowQuality: false};
}

function meritToLiquid(current: number, earned: number, cap: number): number {
  if (current + earned > cap) return Math.max(0, cap - current);
  return earned;
}

function meritToHold(current: number, earned: number, cap: number): number {
  const liquid = meritToLiquid(current, earned, cap);
  return earned - liquid;
}

// A failed/repeated worker must not replace an already committed evaluation.
async function failPendingSubmission(
  submissionRef: import("firebase-admin/firestore").DocumentReference,
  evaluationError: string
): Promise<boolean> {
  return db.runTransaction(async (tx) => {
    const current = await tx.get(submissionRef);
    const status = current.get("status");
    if (!current.exists || (status && status !== "PENDING")) return false;
    tx.update(submissionRef, {status: "FAILED", evaluationError});
    return true;
  });
}

export const submissionEvaluationEngine = onDocumentCreated(
  {
    document: "submissions/{submissionId}",
    region: "us-central1",
    secrets: [OPENAI_API_KEY],
    timeoutSeconds: 540,
    memory: "512MiB",
  },
  async (event) => {
    const snapshot = event.data;
    if (!snapshot) {
      console.log("submissionEvaluationEngine: no snapshot");
      return;
    }

    const data = snapshot.data();
    if (!data) {
      console.log("submissionEvaluationEngine: no data",
        {submissionId: snapshot.id});
      return;
    }

    const submissionRef = snapshot.ref;
    const authorId = data.authorId;
    const playmode = data.playmode ?? "PRACTICE";
    // Preserve invalid/null primary behavior; use the alias only when absent.
    const gamemode = data.gamemode === undefined ? data.gamemodeName : data.gamemode;

    try {
      console.log("submissionEvaluationEngine triggered", {
        submissionId: snapshot.id,
        authorId: authorId ?? null,
        playmode: playmode ?? null,
        gamemode: gamemode ?? null,
        status: data.status ?? null,
      });

      const apiKey = OPENAI_API_KEY.value();

      if (playmode === "TOURNAMENT") {
        console.log("submissionEvaluationEngine: skipped, TOURNAMENT playmode handled by tournamentEvaluationEngine", {
          submissionId: snapshot.id,
        });
        return;
      }

      if (!authorId) {
        console.log("submissionEvaluationEngine: missing authorId", {
          submissionId: snapshot.id,
        });

        await failPendingSubmission(submissionRef, "Missing authorId");

        return;
      }

      if (data.status && data.status !== "PENDING") {
        console.log("submissionEvaluationEngine: skipped, not PENDING", {
          submissionId: snapshot.id,
          status: data.status,
        });
        return;
      }

      const persistedSubmission = await submissionRef.get();
      const persistedStatus = persistedSubmission.get("status");
      if (!persistedSubmission.exists || (persistedStatus && persistedStatus !== "PENDING")) return;

      const content = data.content ?? "";
      const qualityCheck = isContentLowQuality(content);

      if (qualityCheck.isLowQuality) {
        console.log("submissionEvaluationEngine: low quality content rejected", {
          submissionId: snapshot.id,
          reason: qualityCheck.reason,
        });

        const failed = await failPendingSubmission(
          submissionRef, qualityCheck.reason ?? "Invalid content quality."
        );
        if (!failed) return;

        if (playmode === "RANKED") {
          await db.collection("users").doc(authorId).update({
            currentlyInRanked: false,
            rankedSessionStartedAt: FieldValue.delete(),
          });
        }
        return;
      }

      const requiredWords = Array.isArray(data.wordsUsed) ?
        data.wordsUsed
          .map((w: { word?: string } | string) =>
            typeof w === "string" ? w : (w.word ?? "")
          )
          .filter((word: string) => word.length > 0) :
        [];

      console.log("submissionEvaluationEngine: calling R8", {
        submissionId: snapshot.id,
        requiredWordsCount: requiredWords.length,
        wordCount: data.wordCount ?? 0,
      });

      const startOfTodayMs = new Date();
      startOfTodayMs.setUTCHours(0, 0, 0, 0);

      let submissionsToday = 0;
      try {
        const todaySubmissionsSnap = await db.collection("submissions")
          .where("authorId", "==", authorId)
          .where("timestamp", ">=", startOfTodayMs.getTime())
          .get();
        submissionsToday = todaySubmissionsSnap.size;
      } catch (indexErr) {
        console.warn("submissionEvaluationEngine: could not fetch daily submission count (composite index may be missing):", indexErr);
      }

      const userSnapForContext = await db.collection("users").doc(authorId).get();
      const userDataForContext = userSnapForContext.data() ?? {};
      const contextStreak = Number(userDataForContext.currentStreak ?? 0);
      const contextRecentScores = Array.isArray(userDataForContext.recentScores) ? userDataForContext.recentScores : [];

      const result = await evaluateWithR8({
        apiKey,
        content: content,
        gamemode: gamemode ?? "STANDARD",
        requiredWords,
        themeName: data.themeName ?? null,
        topicName: data.topicName ?? null,
        submissionsToday,
        currentStreak: contextStreak,
        recentScores: contextRecentScores,
      });

      console.log("submissionEvaluationEngine: evaluation completed", {
        submissionId: snapshot.id,
        finalScore: result.finalScore,
        source: result.source,
      });

      const userRef = db.collection("users").doc(authorId);
      let leagueToIncrement: string | null = null;

      const evaluationCommitted = await db.runTransaction(async (tx) => {
        leagueToIncrement = null;
        const currentSubmission = await tx.get(submissionRef);
        const currentStatus = currentSubmission.get("status");
        if (!currentSubmission.exists || (currentStatus && currentStatus !== "PENDING")) return false;
        const userSnap = await tx.get(userRef);
        if (!userSnap.exists) {
          throw new Error("User not found for submission evaluation");
        }

        const userData = userSnap.data() ?? {};
        const currentMerit = Number(userData.merit ?? 0);
        const meritCap = Number(userData.meritCap ?? 50000);
        const currentBestScore = Number(userData.bestScore ?? 0);
        const isPlaced = userData.isPlaced === true;

        const today = getUtcDayInt();
        const lastDay = Number(userData.lastSubmissionDay ?? 0);
        const currentStreak = Number(userData.currentStreak ?? 0);

        let newStreak = 1;
        if (lastDay > 0) {
          const yesterday = new Date();
          yesterday.setUTCDate(yesterday.getUTCDate() - 1);
          const yesterdayInt = yesterday.getUTCFullYear() * 10000 + (yesterday.getUTCMonth() + 1) * 100 + yesterday.getUTCDate();

          if (lastDay === today) {
            newStreak = currentStreak;
          } else if (lastDay === yesterdayInt) {
            newStreak = currentStreak + 1;
          } else {
            newStreak = 1;
          }
        }

        const streakMultiplier = getStreakMultiplier(newStreak);

        const meritEarned = Math.floor(calculateMerit(
          result.finalScore,
          data.wordCount ?? 0,
          gamemode,
          playmode === "RANKED" || playmode === "TOURNAMENT"
        ) * streakMultiplier);

        const liquidReward = meritToLiquid(currentMerit, meritEarned, meritCap);
        const holdReward = meritToHold(currentMerit, meritEarned, meritCap);
        const newMerit = currentMerit + liquidReward;

        const userUpdates: Record<string, unknown> = {
          merit: newMerit,
          currentStreak: newStreak,
          lastSubmissionDay: today,
          meritHold: FieldValue.increment(holdReward),
          submissionsCount: FieldValue.increment(1),
          totalMeritEarned: FieldValue.increment(meritEarned),
        };

        if (playmode === "RANKED" || playmode === "TOURNAMENT") {
          userUpdates.bestScore = Math.max(currentBestScore, result.finalScore);
        }

        let ratingChangeResult = 0;

        if (playmode === "RANKED" || playmode === "TOURNAMENT") {
          const recentScores: number[] = Array.isArray(userData.recentScores) ? userData.recentScores : [];
          recentScores.push(result.finalScore);
          // Fix #5: Cap recentScores at 50 entries to prevent document bloat and ensure fast loading.
          userUpdates.recentScores = recentScores.slice(-50);
        }

        if (playmode === "RANKED") {
          if (!isPlaced) {
            const played = (userData.placementMatchesPlayed ?? 0) + 1;
            const totalScore = (userData.totalPlacementScore ?? 0) + result.finalScore;

            if (played >= 6) {
              const avgScore = totalScore / 6;
              const initialRating = Math.min(120, Math.floor((avgScore / 100) * 120));

              userUpdates.rating = initialRating;
              userUpdates.isPlaced = true;
              userUpdates.placementMatchesPlayed = 6;
              userUpdates.totalPlacementScore = totalScore;
              userUpdates.reputation = onRankedCompleted(Number(userData.reputation ?? 0));
              userUpdates.currentlyInRanked = false;
              userUpdates.rankedSessionStartedAt = FieldValue.delete();

              ratingChangeResult = initialRating;

              if (authorId !== "R8") {
                leagueToIncrement = getLeagueFromRating(initialRating);
              }
            } else {
              userUpdates.placementMatchesPlayed = played;
              userUpdates.totalPlacementScore = totalScore;
              userUpdates.currentlyInRanked = false;
              userUpdates.rankedSessionStartedAt = FieldValue.delete();
            }
          } else {
            const newReputation = onRankedCompleted(
              Number(userData.reputation ?? 0)
            );

            userUpdates.reputation = newReputation;
            userUpdates.currentlyInRanked = false;
            userUpdates.rankedSessionStartedAt = FieldValue.delete();
          }
        }

        tx.update(submissionRef, {
          evaluation: {
            submissionId: snapshot.id,
            finalScore: result.finalScore,
            feedback: result.feedback,
            meritEarned,
            meritToHold: holdReward,
            ratingChange: ratingChangeResult,
            resultStatus: "EVALUATED",
            source: result.source || "real",
          },
          status: "EVALUATED",
          matchStatus: playmode === "RANKED" ? "PENDING" : "UNMATCHED",
          evaluationError: FieldValue.delete(),
        });

        tx.update(userRef, userUpdates);

        if (liquidReward !== 0) {
          const txRef = userRef.collection("meritTransactions").doc();
          tx.set(txRef, {
            amount: liquidReward,
            reason: playmode === "RANKED" ? "RANKED_REWARD" : "PRACTICE_REWARD",
            timestamp: Date.now(),
            balanceAfter: newMerit,
          });
        }
        return true;
      });
      if (!evaluationCommitted) return;

      // Optimization: Update global stats outside the transaction to prevent contention/timeouts
      if (leagueToIncrement) {
        db.collection("metadata").doc("rankings").set({
          leagueCounts: {
            [leagueToIncrement]: FieldValue.increment(1),
          },
        }, {merge: true}).catch((err) => console.error("Global stats update failed:", err));
      }

      if (playmode === "RANKED") {
        const authorUserSnap = await db.collection("users").doc(authorId).get();
        const authorName = authorUserSnap.data()?.name ?? "Unknown";
        const authorRating = Number(authorUserSnap.data()?.rating ?? 0);

        await tryMatchRankedSubmission(
          snapshot.id,
          authorId,
          result.finalScore,
          authorRating,
          authorName
        ).catch((err) => {
          console.error("tryMatchRankedSubmission failed:", err);
        });
      }

      pruneOldSubmissions(authorId).catch((err) => {
        console.error("Non-critical background task (pruning) failed:", err);
      });
    } catch (error) {
      console.error("submissionEvaluationEngine failed", error);
      const failed = await failPendingSubmission(
        submissionRef, error instanceof Error ? error.message : "Unknown failure"
      );
      if (!failed) return;
      if (authorId && playmode === "RANKED") {
        try {
          await db.collection("users").doc(authorId).update({
            currentlyInRanked: false,
            rankedSessionStartedAt: FieldValue.delete(),
          });
          console.log("submissionEvaluationEngine: cleaned up session after failure");
        } catch (cleanupError) {
          console.error("submissionEvaluationEngine: failed cleanup", cleanupError);
        }
      }
    }
  }
);

functions/src/tips/tipProcessor.ts.before_text:
import {onDocumentCreated} from "firebase-functions/v2/firestore";
import {db, FieldValue} from "../firebase/admin";

function meritToLiquid(current: number, earned: number, cap: number): number {
  if (current + earned > cap) return Math.max(0, cap - current);
  return earned;
}

function meritToHold(current: number, earned: number, cap: number): number {
  const liquid = meritToLiquid(current, earned, cap);
  return earned - liquid;
}

export const onTipCreated = onDocumentCreated(
  {
    document: "tournaments/{tournamentId}/tips/{tipId}",
    region: "us-central1",
  },
  async (event) => {
    const tip = event.data?.data();
    if (!tip) return;

    const tournamentId = event.params.tournamentId;

    const {tipperId, recipientId, amount, processed} = tip;

    if (!tipperId || !recipientId || !amount) {
      console.log("Invalid tip data");
      return;
    }

    if (tipperId === recipientId) {
      console.log("User attempted to tip themselves");
      return;
    }

    const ALLOWED_AMOUNTS = [100, 150, 200];

    if (!ALLOWED_AMOUNTS.includes(amount)) {
      console.log("Invalid tip amount:", amount);
      return;
    }

    if (processed === true) return;

    if (!event.data) return;
    const tipRef = event.data.ref;

    const tipperRef = db.collection("users").doc(tipperId);
    const recipientRef = db.collection("users").doc(recipientId);

    const submissionQuery = await db
      .collection("tournaments")
      .doc(tournamentId)
      .collection("submissions")
      .where("authorId", "==", recipientId)
      .limit(1)
      .get();

    if (submissionQuery.empty) {
      console.log("Recipient did not submit in this tournament");
      return;
    }

    const duplicateTipQuery = await db
      .collection("tournaments")
      .doc(tournamentId)
      .collection("tips")
      .where("tipperId", "==", tipperId)
      .where("recipientId", "==", recipientId)
      .limit(1)
      .get();

    if (!duplicateTipQuery.empty && duplicateTipQuery.docs[0].id !== event.data.id) {
      console.log("Duplicate tip attempt");
      return;
    }

    try {
      await db.runTransaction(async (tx: FirebaseFirestore.Transaction) => {
        const tipperDoc = await tx.get(tipperRef);
        const recipientDoc = await tx.get(recipientRef);

        if (!tipperDoc.exists) throw new Error("Tipper not found");
        if (!recipientDoc.exists) throw new Error("Recipient not found");

        const tipperData = tipperDoc.data() || {};
        const recipientData = recipientDoc.data() || {};

        const tipperMerit = tipperData.merit ?? 0;
        const recipientMerit = recipientData.merit ?? 0;
        const meritCap = recipientData.meritCap ?? 50000;

        if (tipperMerit < amount) {
          throw new Error("Insufficient merit");
        }

        const liquid = meritToLiquid(recipientMerit, amount, meritCap);
        const hold = meritToHold(recipientMerit, amount, meritCap);

        const newTipperBalance = tipperMerit - amount;
        const newRecipientBalance = recipientMerit + liquid;

        tx.update(tipperRef, {
          merit: newTipperBalance,
        });

        tx.update(recipientRef, {
          merit: newRecipientBalance,
          meritHold: FieldValue.increment(hold),
        });

        tx.update(tipRef, {
          processed: true,
        });

        const tipperTxRef = tipperRef.collection("meritTransactions").doc();
        tx.set(tipperTxRef, {
          amount: -amount,
          reason: "TIP_SENT",
          timestamp: Date.now(),
          balanceAfter: newTipperBalance,
        });

        if (liquid !== 0) {
          const recipientTxRef = recipientRef.collection("meritTransactions").doc();
          tx.set(recipientTxRef, {
            amount: liquid,
            reason: "TIP_RECEIVED",
            timestamp: Date.now(),
            balanceAfter: newRecipientBalance,
          });
        }
      });

      console.log("Tip processed successfully");
    } catch (err) {
      console.error("Tip transaction failed:", err);
    }
  }
);

functions/src/tournaments/createUserTour.before_text:
import {onCall, HttpsError} from "firebase-functions/v2/https";
import {db} from "../firebase/admin";
import {calculateTournamentProjection} from "./systemTournamentEconomy";

type TournamentRequirements = {
  minRating?: number | null;
  maxRating?: number | null;
  minReputation?: number | null;
  minMerit?: number | null;
};

export const createUserTournament = onCall(
  {
    region: "us-central1",
  },
  async (request) => {
    const uid = request.auth?.uid;
    if (!uid) {
      throw new HttpsError("unauthenticated", "You must be signed in.");
    }

    const title = String(request.data?.title ?? "").trim();
    const gamemode = String(request.data?.gamemode ?? "STANDARD").trim();
    const prizePool = Number(request.data?.prizePool ?? 0);
    const maxPlayers = Number(request.data?.maxPlayers ?? 0);

    const requirements = (request.data?.requirements ?? {}) as
     TournamentRequirements;

    if (!title) {
      throw new HttpsError("invalid-argument", "Missing tournament title.");
    }

    if (gamemode !== "STANDARD" && gamemode !== "ON_TOPIC") {
      throw new HttpsError("invalid-argument", "Invalid gamemode.");
    }

    if (!Number.isFinite(prizePool) || prizePool < 5000) {
      throw new HttpsError(
        "invalid-argument",
        "Prize pool must be at least 5000."
      );
    }

    if (!Number.isFinite(maxPlayers) || maxPlayers < 2 || maxPlayers > 100) {
      throw new HttpsError(
        "invalid-argument",
        "Max players must be between 2 and 100."
      );
    }

    const minPlayers = 6;

    const userRef = db.collection("users").doc(uid);
    const tournamentRef = db.collection("tournaments").doc();

    await db.runTransaction(async (tx) => {
      const userSnap = await tx.get(userRef);

      if (!userSnap.exists) {
        throw new HttpsError("not-found", "User not found.");
      }

      const user = userSnap.data();
      const currentMerit = user?.merit ?? 0;
      const creatorName = user?.name ?? "Unknown Host";
      const creatorImageURL = user?.profileImageURL ?? "";

      const projection = calculateTournamentProjection({
        prizePool,
        maxPlayers,
      });

      const totalCost = prizePool + projection.systemFee;

      if (currentMerit < totalCost) {
        throw new HttpsError("failed-precondition", "Insufficient Merit to cover Prize Pool and System Fee.");
      }

      const now = Date.now();
      const enrollmentDeadline = now + (12 * 60 * 60 * 1000);
      const submissionDeadline = enrollmentDeadline + (24 * 60 * 60 * 1000);

      const newBalance = currentMerit - totalCost;

      tx.update(userRef, {
        merit: newBalance,
      });

      tx.set(tournamentRef, {
        id: tournamentRef.id,
        title,
        creatorId: uid,
        creatorName,
        creatorImageURL,
        prizePool,
        maxPlayers,
        minPlayers,
        playersCount: 0,
        submissionsCount: 0,
        entranceFee: projection.entranceFee,
        systemFee: projection.systemFee,
        enrollmentDeadline,
        submissionDeadline,
        nextPhaseCheckAt: enrollmentDeadline,
        refunded: false,
        requirements: {
          minRating: requirements.minRating ?? null,
          maxRating: requirements.maxRating ?? null,
          minReputation: requirements.minReputation ?? null,
          minMerit: requirements.minMerit ?? null,
        },
        status: "ENROLLING",
        strictnessMultiplier: 0.92,
        createdAt: now,
        gamemode,
        requiredWords: [],
        themeId: null,
        themeName: null,
        topicId: null,
        topicName: null,
        isSystemHosted: false,
      });

      const txRef = userRef.collection("meritTransactions").doc();
      tx.set(txRef, {
        amount: -totalCost,
        reason: "CREATE_TOURNAMENT",
        timestamp: now,
        balanceAfter: newBalance,
      });
    });

    return {
      success: true,
      tournamentId: tournamentRef.id,
    };
  }
);

functions/src/tournaments/enrollInTourna.before_text:
import {onCall, HttpsError} from "firebase-functions/v2/https";
import {db, FieldValue} from "../firebase/admin";

export const enrollInTournament = onCall(
  {
    region: "us-central1",
  },
  async (request) => {
    const uid = request.auth?.uid;
    if (!uid) {
      throw new HttpsError("unauthenticated", "You must be signed in.");
    }

    const tournamentId = request.data.tournamentId;
    if (!tournamentId || typeof tournamentId !== "string") {
      throw new HttpsError("invalid-argument", "Missing tournamentId.");
    }

    const tournamentRef = db.collection("tournaments").doc(tournamentId);
    const enrollmentRef = tournamentRef.collection("enrollments").doc(uid);
    const userRef = db.collection("users").doc(uid);

    try {
      await db.runTransaction(async (tx) => {
        const tournamentSnap = await tx.get(tournamentRef);
        if (!tournamentSnap.exists) {
          throw new HttpsError("not-found", "Tournament not found.");
        }

        const tournament = tournamentSnap.data();
        if (!tournament) {
          throw new HttpsError("internal", "Invalid tournament data.");
        }

        if (uid === tournament.creatorId) {
          throw new HttpsError("failed-precondition", "Host cannot enroll.");
        }

        if (tournament.status !== "ENROLLING") {
          throw new HttpsError("failed-precondition", "Enrollment closed.");
        }

        if (Date.now() > tournament.enrollmentDeadline) {
          throw new HttpsError("failed-precondition",
            "Enrollment period ended.");
        }

        if (tournament.playersCount >= tournament.maxPlayers) {
          throw new HttpsError("failed-precondition", "Tournament is full.");
        }

        const existingEnrollment = await tx.get(enrollmentRef);
        if (existingEnrollment.exists) {
          throw new HttpsError("already-exists", "Already enrolled.");
        }

        const userSnap = await tx.get(userRef);
        if (!userSnap.exists) {
          throw new HttpsError("not-found", "User not found.");
        }

        const user = userSnap.data();
        const currentMerit = user?.merit ?? 0;
        const entranceFee = tournament.entranceFee;

        if (currentMerit < entranceFee) {
          throw new HttpsError("failed-precondition", "Not enough Merit.");
        }

        const newBalance = currentMerit - entranceFee;

        tx.update(userRef, {
          merit: newBalance,
        });

        tx.set(enrollmentRef, {
          joinedAt: Date.now(),
          userId: uid,
        });

        tx.update(tournamentRef, {
          playersCount: FieldValue.increment(1),
        });

        const txRef = userRef.collection("meritTransactions").doc();
        tx.set(txRef, {
          amount: -entranceFee,
          reason: "ENTER_TOURNAMENT",
          timestamp: Date.now(),
          balanceAfter: newBalance,
        });
      });

      return {
        success: true,
        message: "Enrolled successfully.",
      };
    } catch (error) {
      if (error instanceof HttpsError) {
        throw error;
      }

      console.error("enrollInTournament failed:", error);
      throw new HttpsError("internal", "Failed to enroll in tournament.");
    }
  }
);

functions/src/tournaments/evaluationEngi.before_text:
import {onDocumentUpdated} from "firebase-functions/v2/firestore";
import {db, FieldValue} from "../firebase/admin";
import {calculateRewardPercentages} from "../utils/tournamentRewards";
import {OPENAI_API_KEY, evaluateWithR8} from "../r8/evaluateWithR8";

type EvaluatedSubmission = {
  authorId: string;
  score: number;
  feedback: string;
  source: string;
  submissionRef: FirebaseFirestore.DocumentReference;
};

function getUtcDayInt(): number {
  const now = new Date();
  return now.getUTCFullYear() * 10000 + (now.getUTCMonth() + 1) * 100 + now.getUTCDate();
}

function meritToLiquid(current: number, earned: number, cap: number): number {
  if (current + earned > cap) return Math.max(0, cap - current);
  return earned;
}

function meritToHold(current: number, earned: number, cap: number): number {
  const liquid = meritToLiquid(current, earned, cap);
  return earned - liquid;
}

export const tournamentEvaluationEngine = onDocumentUpdated(
  {
    document: "tournaments/{tournamentId}",
    region: "us-central1",
    secrets: [OPENAI_API_KEY],
    timeoutSeconds: 540,
    memory: "512MiB",
  },
  async (event) => {
    const before = event.data?.before.data();
    const after = event.data?.after.data();

    if (!before || !after) return;

    if (before.status !== "EVALUATING" && after.status === "EVALUATING") {
      const tournamentId = event.params.tournamentId;
      const tournamentRef = db.collection("tournaments").doc(tournamentId);

      if (after.playersCount < after.minPlayers) {
        await tournamentRef.update({
          status: "CANCELLED",
          cancelledAt: Date.now(),
        });
        return;
      }

      const submissionsSnapshot = await tournamentRef
        .collection("submissions")
        .get();

      const apiKey = OPENAI_API_KEY.value();

      const evaluated: EvaluatedSubmission[] = [];

      for (const doc of submissionsSnapshot.docs) {
        const data = doc.data();
        let result;
        try {
          result = await evaluateWithR8({
            apiKey,
            content: data.content ?? "",
            gamemode: after.gamemode ?? "STANDARD",
            requiredWords: Array.isArray(after.requiredWords) ?
              after.requiredWords : [],
            themeName: after.themeName ?? null,
            topicName: after.topicName ?? null,
          });
        } catch (err) {
          console.error(`Evaluation failed for submission ${doc.id}:`, err);
          result = {finalScore: 0, feedback: "Evaluation unavailable.", source: "mock"};
        }

        evaluated.push({
          authorId: data.authorId,
          score: result.finalScore,
          feedback: result.feedback,
          source: result.source || "mock",
          submissionRef: doc.ref,
        });
      }

      evaluated.sort((a, b) => b.score - a.score);

      const rewardPercentages = calculateRewardPercentages(evaluated.length);
      const today = getUtcDayInt();

      for (let i = 0; i < evaluated.length; i++) {
        const entry = evaluated[i];
        const rank = i + 1;
        const rewardPercent = rewardPercentages[i] ?? 0;
        const reward = Math.floor(after.prizePool * rewardPercent);

        const userRef = db.collection("users").doc(entry.authorId);

        await db.runTransaction(async (tx) => {
          const userSnap = await tx.get(userRef);
          if (!userSnap.exists) return;

          const userData = userSnap.data() || {};
          const currentMerit = userData.merit ?? 0;
          const meritCap = userData.meritCap ?? 50000;

          const liquid = reward > 0 ? meritToLiquid(currentMerit, reward, meritCap) : 0;
          const hold = reward > 0 ? meritToHold(currentMerit, reward, meritCap) : 0;
          const newMerit = currentMerit + liquid;

          const recentScores: number[] = Array.isArray(userData.recentScores) ? userData.recentScores : [];
          recentScores.push(entry.score);

          const lastDay = Number(userData.lastSubmissionDay ?? 0);
          const currentStreak = Number(userData.currentStreak ?? 0);
          let newStreak = currentStreak;

          if (lastDay !== today) {
            const yesterday = new Date();
            yesterday.setUTCDate(yesterday.getUTCDate() - 1);
            const yesterdayInt = yesterday.getUTCFullYear() * 10000 + (yesterday.getUTCMonth() + 1) * 100 + yesterday.getUTCDate();
            newStreak = (lastDay === yesterdayInt) ? currentStreak + 1 : 1;
          }

          const userUpdates: Record<string, unknown> = {
            merit: newMerit,
            meritHold: FieldValue.increment(hold),
            submissionsCount: FieldValue.increment(1),
            bestScore: Math.max(userData.bestScore || 0, entry.score),
            recentScores: recentScores.slice(-20),
            tournamentsPlayed: FieldValue.increment(1),
            totalMeritEarned: FieldValue.increment(reward),
            lastSubmissionDay: today,
            currentStreak: newStreak,
          };

          if (rank === 1) {
            userUpdates.tournamentsWon = FieldValue.increment(1);
          }

          tx.update(userRef, userUpdates);

          tx.update(entry.submissionRef, {
            evaluation: {
              submissionId: entry.submissionRef.id,
              finalScore: entry.score,
              feedback: entry.feedback,
              meritEarned: reward,
              meritToHold: hold,
              ratingChange: 0,
              rankLeaderboard: rank,
              resultStatus: "EVALUATED",
              source: entry.source,
            },
            status: "EVALUATED",
          });

          if (liquid !== 0) {
            const txRef = userRef.collection("meritTransactions").doc();
            tx.set(txRef, {
              amount: liquid,
              reason: "TOURNAMENT_REWARD",
              timestamp: Date.now(),
              balanceAfter: newMerit,
            });
          }
        });
      }

      const totalRevenue = after.entranceFee * after.playersCount;
      const hostProfit = totalRevenue - after.prizePool - after.systemFee;

      if (hostProfit > 0) {
        const hostRef = db.collection("users").doc(after.creatorId);
        await db.runTransaction(async (tx) => {
          const hostSnap = await tx.get(hostRef);
          if (!hostSnap.exists) return;

          const hostData = hostSnap.data() || {};
          const currentMerit = hostData.merit ?? 0;
          const meritCap = hostData.meritCap ?? 50000;

          const liquid = meritToLiquid(currentMerit, hostProfit, meritCap);
          const hold = meritToHold(currentMerit, hostProfit, meritCap);
          const newMerit = currentMerit + liquid;

          tx.update(hostRef, {
            merit: newMerit,
            meritHold: FieldValue.increment(hold),
            totalMeritEarned: FieldValue.increment(hostProfit),
          });

          if (liquid !== 0) {
            const txRef = hostRef.collection("meritTransactions").doc();
            tx.set(txRef, {
              amount: liquid,
              reason: "TOURNAMENT_REWARD",
              timestamp: Date.now(),
              balanceAfter: newMerit,
            });
          }
        });
      }

      await tournamentRef.update({
        status: "COMPLETED",
        completedAt: Date.now(),
      });
    }
  }
);

