functions/src/tournaments/phaseControlle.before_text:
import {onSchedule} from "firebase-functions/v2/scheduler";
import {db} from "../firebase/admin";
import {FieldValue} from "firebase-admin/firestore";

async function getRandomWords(count: number): Promise<string[]> {
  const randomOffset = Math.random();
  const snapshot = await db.collection("words")
    .where("isActive", "==", true)
    .where("randomIndex", ">=", randomOffset)
    .limit(count)
    .get();

  const results: string[] = [];
  snapshot.docs.forEach((doc) => {
    const word = doc.data().word as string;
    if (word) results.push(word);
  });

  if (results.length < count) {
    const remaining = count - results.length;
    const secondSnapshot = await db.collection("words")
      .where("isActive", "==", true)
      .where("randomIndex", "<", randomOffset)
      .limit(remaining)
      .get();

    secondSnapshot.docs.forEach((doc) => {
      const word = doc.data().word as string;
      if (word) results.push(word);
    });
  }
  return results.sort(() => Math.random() - 0.5);
}

async function getRandomThemeAndTopic(): Promise<{
  themeId: string;
  themeName: string;
  topicId: string;
  topicName: string;
}> {
  const themesSnapshot = await db.collection("themes").get();
  const themes = themesSnapshot.docs;
  if (themes.length === 0) throw new Error("No themes found");

  const randomTheme = themes[Math.floor(Math.random() * themes.length)];
  const themeData = randomTheme.data();

  const topicsSnapshot = await db.collection("topics")
    .where("themeId", "==", randomTheme.id)
    .get();

  const topics = topicsSnapshot.docs;
  if (topics.length === 0) throw new Error("No topics found for selected theme");

  const randomTopic = topics[Math.floor(Math.random() * topics.length)];
  const topicData = randomTopic.data();

  return {
    themeId: randomTheme.id,
    themeName: themeData.name ?? "Unknown Theme",
    topicId: randomTopic.id,
    topicName: topicData.name ?? "Unknown Topic",
  };
}

interface TournamentUpdates {
  updatedAt: FieldValue;
  status?: string;
  nextPhaseCheckAt?: number | FieldValue;
  themeId?: string;
  themeName?: string;
  topicId?: string;
  topicName?: string;
  requiredWords?: string[];
  [key: string]: string | number | FieldValue | string[] | undefined;
}

export const tournamentPhaseController = onSchedule("every 15 minutes", async () => {
  const now = Date.now();

  const snapshot = await db.collection("tournaments")
    .where("status", "in", ["ENROLLING", "ACTIVE"])
    .where("nextPhaseCheckAt", "<=", now)
    .orderBy("nextPhaseCheckAt", "asc")
    .limit(20)
    .get();

  if (snapshot.empty) return;

  for (const doc of snapshot.docs) {
    const data = doc.data();
    const updates: TournamentUpdates = {
      updatedAt: FieldValue.serverTimestamp(),
    };

    if (data.status === "ENROLLING" && now >= data.enrollmentDeadline) {
      const gameContent = await getRandomThemeAndTopic();
      const gameWords = await getRandomWords(10);

      updates.status = "ACTIVE";
      updates.nextPhaseCheckAt = data.submissionDeadline;
      updates.themeId = gameContent.themeId;
      updates.themeName = gameContent.themeName;
      updates.topicId = gameContent.topicId;
      updates.topicName = gameContent.topicName;
      updates.requiredWords = gameWords;
    } else if (data.status === "ACTIVE" && now >= data.submissionDeadline) {
      updates.status = "EVALUATING";
      updates.nextPhaseCheckAt = FieldValue.delete();
    }

    if (updates.status) {
      await doc.ref.update(updates);
    }
  }
});

functions/src/tournaments/pruneOldTourna.before_text:
import {onSchedule} from "firebase-functions/v2/scheduler";
import * as admin from "firebase-admin";

export const pruneOldTournaments = onSchedule("every 12 hours", async () => {
  const db = admin.firestore();
  const now = Date.now();
  const TWENTY_FOUR_HOURS_MS = 24 * 60 * 60 * 1000;

  try {
    const cancelledSnapshot = await db.collection("tournaments")
      .where("status", "==", "CANCELLED")
      .get();

    if (!cancelledSnapshot.empty) {
      await Promise.all(cancelledSnapshot.docs.map((doc) => db.recursiveDelete(doc.ref)));
      console.log(`Pruned ${cancelledSnapshot.size} cancelled tournaments recursively.`);
    }

    const completedSnapshot = await db.collection("tournaments")
      .where("status", "==", "COMPLETED")
      .get();

    if (!completedSnapshot.empty) {
      const toDelete = completedSnapshot.docs.filter((doc) => {
        const data = doc.data();
        const timestamp = data.completedAt || data.createdAt || 0;
        return now - timestamp > TWENTY_FOUR_HOURS_MS;
      });

      if (toDelete.length > 0) {
        await Promise.all(toDelete.map((doc) => db.recursiveDelete(doc.ref)));
        console.log(`Pruned ${toDelete.length} completed tournaments recursively.`);
      }
    }
  } catch (error) {
    console.error("Error pruning old tournaments:", error);
  }
});

functions/src/tournaments/refundEngine.t.before_text:
import {onDocumentUpdated} from "firebase-functions/v2/firestore";
import {db} from "../firebase/admin";

export const tournamentRefundEngine = onDocumentUpdated(
  {
    document: "tournaments/{tournamentId}",
    region: "us-central1",
  },
  async (event) => {
    const before = event.data?.before.data();
    const after = event.data?.after.data();

    if (!before || !after) return;

    if (before.status !== "CANCELLED" && after.status === "CANCELLED") {
      if (after.refunded === true) return;

      const tournamentId = event.params.tournamentId;
      const tournamentRef = db.collection("tournaments").doc(tournamentId);

      const enrollmentsSnapshot = await tournamentRef.collection("enrollments").get();

      for (const doc of enrollmentsSnapshot.docs) {
        const userId = doc.id;
        const userRef = db.collection("users").doc(userId);

        await db.runTransaction(async (tx) => {
          const userSnap = await tx.get(userRef);
          if (!userSnap.exists) return;

          const currentMerit = userSnap.data()?.merit ?? 0;
          const refundAmount = after.entranceFee;
          const newBalance = currentMerit + refundAmount;

          tx.update(userRef, {
            merit: newBalance,
          });

          const txRef = userRef.collection("meritTransactions").doc();
          tx.set(txRef, {
            amount: refundAmount,
            reason: "REFUND_TOURNAMENT",
            timestamp: Date.now(),
            balanceAfter: newBalance,
          });
        });
      }

      const hostRef = db.collection("users").doc(after.creatorId);
      await db.runTransaction(async (tx) => {
        const hostSnap = await tx.get(hostRef);
        if (!hostSnap.exists) return;

        const currentMerit = hostSnap.data()?.merit ?? 0;
        const refundAmount = after.prizePool;
        const newBalance = currentMerit + refundAmount;

        tx.update(hostRef, {
          merit: newBalance,
        });

        const txRef = hostRef.collection("meritTransactions").doc();
        tx.set(txRef, {
          amount: refundAmount,
          reason: "REFUND_TOURNAMENT",
          timestamp: Date.now(),
          balanceAfter: newBalance,
        });
      });

      await tournamentRef.update({
        refunded: true,
      });
    }
  }
);

functions/src/tournaments/submissionWatc.before_text:
import {onDocumentCreated} from "firebase-functions/v2/firestore";
import {db} from "../firebase/admin";

export const submissionCompletionWatcher = onDocumentCreated(
  {
    document: "tournaments/{tournamentId}/submissions/{submissionId}",
    region: "us-central1",
  },
  async (event) => {
    const tournamentId = event.params.tournamentId;

    const tournamentRef = db.collection("tournaments").doc(tournamentId);

    const tournamentSnapshot = await tournamentRef.get();
    const tournament = tournamentSnapshot.data();

    if (!tournament) return;

    // Only care during ACTIVE phase
    if (tournament.status !== "ACTIVE") return;

    const submissionsSnapshot = await tournamentRef
      .collection("submissions")
      .get();

    const submissionsCount = submissionsSnapshot.size;

    // All players submitted → start evaluation early
    if (submissionsCount === tournament.playersCount) {
      await tournamentRef.update({
        status: "EVALUATING",
      });
    }
  }
);

functions/src/tournaments/systemTourname.before_text:
export const R8_USER_ID = "R8";
export const R8_USER_NAME = "R8";

export const SYSTEM_TOURNAMENT_ENROLLMENT_DURATION_MS =
  12 * 60 * 60 * 1000;

export const SYSTEM_TOURNAMENT_SUBMISSION_DURATION_MS =
  24 * 60 * 60 * 1000;

export const SYSTEM_TOURNAMENT_CHECK_STATUSES = [
  "ENROLLING",
  "ACTIVE",
];

export const SYSTEM_PRIZE_POOL_STEP = 100;

export const STANDARD_SYSTEM_TOURNAMENT_CONFIG = {
  gamemode: "STANDARD",
  titlePrefix: "Standard Tournament Edition ",
  minPrizePool: 6000,
  maxPrizePool: 12000,
  maxPlayers: 20,
  minPlayers: 6,
  requirements: {
    minRating: null,
    maxRating: null,
