  breakEvenPlayers: number;
};

export function calculateTournamentProjection(params: {
  prizePool: number;
  maxPlayers: number;
}): TournamentEconomyProjection {
  const {prizePool, maxPlayers} = params;

  if (prizePool <= 0) {
    throw new Error("Prize pool must be positive");
  }

  if (maxPlayers <= 1) {
    throw new Error("At least 2 players required");
  }

  const systemFee = Math.floor(prizePool * SYSTEM_CREATION_FEE_PERCENT);

  const targetRevenue = Math.floor(prizePool * (1 + PROFIT_MARGIN_PERCENT));

  const entranceFee = Math.ceil(targetRevenue / maxPlayers);

  const totalRevenue = entranceFee * maxPlayers;

  const netProfit = totalRevenue - prizePool - systemFee;

  const breakEvenPlayers = Math.ceil((prizePool + systemFee) / entranceFee);

  return {
    prizePool,
    maxPlayers,
    entranceFee,
    totalRevenue,
    systemFee,
    netProfit,
    breakEvenPlayers,
  };
}

export function getRandomPrizePool(params: {
  minPrizePool: number;
  maxPrizePool: number;
  step: number;
}): number {
  const {minPrizePool, maxPrizePool, step} = params;

  if (minPrizePool > maxPrizePool) {
    throw new Error("minPrizePool cannot be greater than maxPrizePool");
  }

  if (step <= 0) {
    throw new Error("step must be positive");
  }

  const numberOfSteps = Math.floor((maxPrizePool - minPrizePool) / step);
  const randomStep = Math.floor(Math.random() * (numberOfSteps + 1));

  return minPrizePool + (randomStep * step);
}

import {onSchedule} from "firebase-functions/v2/scheduler";
import {db} from "../firebase/admin";
import {
  R8_USER_ID,
  R8_USER_NAME,
  STANDARD_SYSTEM_TOURNAMENT_CONFIG,
  ON_TOPIC_SYSTEM_TOURNAMENT_CONFIG,
  SYSTEM_TOURNAMENT_CHECK_STATUSES,
  SYSTEM_TOURNAMENT_ENROLLMENT_DURATION_MS,
  SYSTEM_TOURNAMENT_SUBMISSION_DURATION_MS,
  SYSTEM_PRIZE_POOL_STEP,
} from "./systemTournamentConfig";
import {calculateTournamentProjection} from "./systemTournamentEconomy";
import {getRandomPrizePool} from "./systemTournamentPrizePool";

type SystemTournamentConfig = {
  gamemode: string;
  titlePrefix: string;
  minPrizePool: number;
  maxPrizePool: number;
  maxPlayers: number;
  minPlayers: number;
  requirements: {
    minRating: number | null;
    maxRating: number | null;
    minReputation: number | null;
    minMerit: number | null;
  };
};

async function countOpenSystemTournamentsByGamemode(
  gamemode: string
): Promise<number> {
  const snapshot = await db
    .collection("tournaments")
    .where("isSystemHosted", "==", true)
    .where("gamemode", "==", gamemode)
    .where("status", "in", SYSTEM_TOURNAMENT_CHECK_STATUSES)
    .get();

  return snapshot.size;
}

async function getNextSystemTournamentNumber(
  gamemode: string
): Promise<number> {
  const snapshot = await db
    .collection("tournaments")
    .where("isSystemHosted", "==", true)
    .where("gamemode", "==", gamemode)
    .get();

  return snapshot.size + 1;
}

async function createSystemTournament(
  config: SystemTournamentConfig
): Promise<void> {
  const now = Date.now();

  const enrollmentDeadline = now + SYSTEM_TOURNAMENT_ENROLLMENT_DURATION_MS;
  const submissionDeadline =
    enrollmentDeadline + SYSTEM_TOURNAMENT_SUBMISSION_DURATION_MS;

  const prizePool = getRandomPrizePool({
    minPrizePool: config.minPrizePool,
    maxPrizePool: config.maxPrizePool,
    step: SYSTEM_PRIZE_POOL_STEP,
  });

  const projection = calculateTournamentProjection({
    prizePool,
    maxPlayers: config.maxPlayers,
  });

  const tournamentNumber = await getNextSystemTournamentNumber(config.gamemode);

  const tournamentRef = db.collection("tournaments").doc();

  await tournamentRef.set({
    id: tournamentRef.id,
    title: `${config.titlePrefix} #${tournamentNumber}`,
    creatorId: R8_USER_ID,
    creatorName: R8_USER_NAME,
    prizePool,
    maxPlayers: config.maxPlayers,
    minPlayers: config.minPlayers,
    playersCount: 0,
    submissionsCount: 0,
    entranceFee: projection.entranceFee,
    systemFee: projection.systemFee,
    enrollmentDeadline,
    submissionDeadline,
    nextPhaseCheckAt: enrollmentDeadline,
    refunded: false,
    requirements: config.requirements,
    status: "ENROLLING",
    strictnessMultiplier: 0.92,
    createdAt: now,
    gamemode: config.gamemode,
    requiredWords: [],
    themeId: null,
    themeName: null,
    topicId: null,
    topicName: null,
    isSystemHosted: true,
  });
}

export const systemTournamentSeeder = onSchedule(
  {
    schedule: "every 24 hours",
    region: "us-central1",
  },
  async () => {
    const standardCount = await
    countOpenSystemTournamentsByGamemode("STANDARD");
    const onTopicCount = await
    countOpenSystemTournamentsByGamemode("ON_TOPIC");

    if (standardCount === 0) {
      await createSystemTournament(STANDARD_SYSTEM_TOURNAMENT_CONFIG);
    }

    if (onTopicCount === 0) {
      await createSystemTournament(ON_TOPIC_SYSTEM_TOURNAMENT_CONFIG);
    }
  }
);

functions/src/users/applyMeritAction.ts.before_text:
import {onCall, HttpsError} from "firebase-functions/v2/https";
import {db, FieldValue} from "../firebase/admin";
import {calculateRankedEntryCost} from "../utils/meritCalculator";
import {onRankedAbandoned} from "../utils/reputationManager";

type MeritAction =
  | "PURCHASE_EXAMPLE_SENTENCE"
  | "PURCHASE_REPUTATION_VIEW"
  | "ENTER_RANKED"
  | "ABANDON_RANKED"
  | "REWARD_PRACTICE"
  | "REWARD_RANKED"
  | "CHANGE_USERNAME"
  | "SAVE_SUBMISSION"
  | "EXPAND_MERIT_CAP";

function validateUsername(username: string): string | null {
  if (username.length < 2) return "Username must be at least 2 characters.";
  if (username.length > 20) return "Username must be at most 20 characters.";

  const allowedRegex = /^[A-Za-z0-9_.,*{}[\]()√]+$/;
  if (!allowedRegex.test(username)) {
    return "Username contains invalid characters.";
  }

  const hasLetterOrDigit = /[A-Za-z0-9]/.test(username);
  if (!hasLetterOrDigit) {
    return "Username must contain at least one letter or number.";
  }

  return null;
}

export const applyMeritAction = onCall(
  {
    region: "us-central1",
  },
  async (request) => {
    const uid = request.auth?.uid;
    if (!uid) {
      throw new HttpsError("unauthenticated", "You must be signed in.");
    }

    const action = request.data?.action as MeritAction | undefined;
    if (!action) {
      throw new HttpsError("invalid-argument", "Missing action.");
    }

    const userRef = db.collection("users").doc(uid);
    let updatedFields: Record<string, unknown> = {};

    await db.runTransaction(async (tx) => {
      const userSnap = await tx.get(userRef);

      if (!userSnap.exists) {
        throw new Error("User not found."); // Caught by transaction and converted to HttpsError if needed
      }

      const user = userSnap.data();
      const currentMerit = user?.merit ?? 0;
      const meritCap = user?.meritCap ?? 50000;
      let rankedWinStreak = user?.rankedWinStreak ?? 0;
      let rankedLossStreak = user?.rankedLossStreak ?? 0;
      let reputation = user?.reputation ?? 0;

      let meritDelta = 0;
      let reason = "";

      switch (action) {
      case "EXPAND_MERIT_CAP": {
        const cost = Math.floor(meritCap * 0.25);
        const expansionAmount = 10000;

        if (currentMerit < cost) {
          throw new Error("Insufficient Merit for expansion.");
        }

        meritDelta = -cost;
        reason = "EXPAND_MERIT_CAP";
        updatedFields = {
          merit: currentMerit - cost,
          meritCap: meritCap + expansionAmount,
        };
        tx.update(userRef, updatedFields);
        break;
      }

      case "PURCHASE_EXAMPLE_SENTENCE": {
        const cost = 25;

        if (currentMerit < cost) {
          throw new Error("Not enough Merit.");
        }

        meritDelta = -cost;
        reason = "PURCHASE_EXAMPLE_SENTENCE";
        updatedFields = {
          merit: currentMerit - cost,
        };
        tx.update(userRef, updatedFields);
        break;
      }

      case "PURCHASE_REPUTATION_VIEW": {
        const cost = 500;

        if (currentMerit < cost) {
          throw new Error("Not enough Merit.");
        }

        meritDelta = -cost;
        reason = "PURCHASE_REPUTATION_VIEW";
        updatedFields = {
          merit: currentMerit - cost,
        };
        tx.update(userRef, updatedFields);
        break;
      }

      case "SAVE_SUBMISSION": {
        const submissionId = request.data?.submissionId;
        if (!submissionId) {
          throw new Error("Missing submissionId.");
        }

        // Optimization: Use cached count instead of transactional query to avoid timeouts
        const savedCount = user?.savedSubmissionsCount ?? 0;
        const cost = 2000 + Math.floor(savedCount / 3) * 200;

        if (currentMerit < cost) {
          throw new Error("Not enough Merit.");
        }

        const subRef = db.collection("submissions").doc(submissionId);
        const subSnap = await tx.get(subRef);

        if (!subSnap.exists) {
          throw new Error("Submission not found.");
        }

        const subData = subSnap.data();
        if (subData?.authorId !== uid) {
          throw new Error("You are not the author.");
        }

        if (subData?.isSaved === true) {
          throw new Error("Submission is already saved.");
        }

        meritDelta = -cost;
        reason = "SAVE_SUBMISSION";
        updatedFields = {
          merit: currentMerit - cost,
          savedSubmissionsCount: FieldValue.increment(1),
        };
        tx.update(userRef, updatedFields);

        tx.update(subRef, {
          isSaved: true,
        });
        break;
      }

      case "ENTER_RANKED": {
        const startOfTodayMs = new Date();
        startOfTodayMs.setUTCHours(0, 0, 0, 0);

        // Transactional queries are expensive. ENTER_RANKED limit check
        // could be further optimized by moving it to a daily counter on the user doc,
        // but for now we keep it and ensure it's the only query.
        let submissionsToday = 0;
        try {
          const todayRankedSnap = await tx.get(db.collection("submissions")
            .where("authorId", "==", uid)
            .where("playmode", "==", "RANKED")
            .where("timestamp", ">=", startOfTodayMs.getTime()));
          submissionsToday = todayRankedSnap.size;
        } catch (indexErr) {
          console.warn("applyMeritAction: daily ranked count query failed", indexErr);
        }

        if (submissionsToday >= 5) {
          throw new Error("Daily ranked limit reached (5). Return tomorrow.");
        }

        if (user?.currentlyInRanked) {
          reputation = onRankedAbandoned(reputation);
          rankedLossStreak += 1;
          rankedWinStreak = 0;
        }

        const cost = calculateRankedEntryCost(
          rankedWinStreak,
          rankedLossStreak,
          reputation
        );

        if (currentMerit < cost) {
          throw new Error("Not enough Merit.");
        }

        const rankedSessionStartedAt = Date.now();
        meritDelta = -cost;
        reason = "ENTER_RANKED";
        updatedFields = {
          merit: currentMerit - cost,
          currentlyInRanked: true,
          rankedSessionStartedAt: rankedSessionStartedAt,
          reputation: reputation,
          rankedLossStreak: rankedLossStreak,
          rankedWinStreak: rankedWinStreak,
        };
        tx.update(userRef, updatedFields);
        break;
      }

      case "ABANDON_RANKED": {
        if (!user?.currentlyInRanked) {
          throw new Error("No active ranked session to abandon.");
        }

        updatedFields = {
          reputation: onRankedAbandoned(reputation),
          rankedLossStreak: rankedLossStreak + 1,
          rankedWinStreak: 0,
          currentlyInRanked: false,
          rankedSessionStartedAt: null,
        };
        tx.update(userRef, updatedFields);
        break;
      }

      case "CHANGE_USERNAME": {
        const cost = 1000;
        const rawNewUsername = String(request.data?.newUsername ?? "").trim();
        const normalizedNewUsername = rawNewUsername.toLowerCase();

        const validationError = validateUsername(rawNewUsername);
        if (validationError) {
          throw new Error(validationError);
        }

        const oldUsername = String(user?.name ?? "").trim();
        const normalizedOldUsername = oldUsername.toLowerCase();

        if (!oldUsername) {
          throw new Error("Current username not found.");
        }

        if (normalizedOldUsername === normalizedNewUsername) {
          throw new Error("That is already your username.");
        }

        if (currentMerit < cost) {
          throw new Error("Not enough Merit.");
        }

        const oldUsernameRef = db.collection("usernames")
          .doc(normalizedOldUsername);
        const newUsernameRef = db.collection("usernames")
          .doc(normalizedNewUsername);
        const newUsernameSnap = await tx.get(newUsernameRef);

        if (newUsernameSnap.exists) {
          throw new Error("That username is already taken.");
        }

        tx.delete(oldUsernameRef);

        tx.set(newUsernameRef, {
          userId: uid,
          username: rawNewUsername,
          normalized: normalizedNewUsername,
          createdAt: Date.now(),
        });

        meritDelta = -cost;
        reason = "CHANGE_USERNAME";
        updatedFields = {
          name: rawNewUsername,
          merit: currentMerit - cost,
        };
        tx.update(userRef, updatedFields);
        break;
      }

      case "REWARD_PRACTICE":
      case "REWARD_RANKED": {
        throw new Error("Action must be applied by backend flow.");
      }

      default:
        throw new Error("Unsupported action.");
      }

      if (meritDelta !== 0) {
        const txRef = userRef.collection("meritTransactions").doc();
        tx.set(txRef, {
          amount: meritDelta,
          reason: reason,
          timestamp: Date.now(),
          balanceAfter: currentMerit + meritDelta,
        });
      }
    }).catch((err) => {
      throw new HttpsError("failed-precondition", err.message);
    });

    return {
      success: true,
      updatedFields,
    };
  }
);

functions/src/users/rankedSessionCleaner.before_text:
import {onSchedule} from "firebase-functions/v2/scheduler";
import {db, FieldValue} from "../firebase/admin";
import {onRankedAbandoned} from "../utils/reputationManager";

export const rankedSessionCleaner = onSchedule("every 15 minutes", async () => {
  const sixtyMinutesAgo = Date.now() - (60 * 60 * 1000);

  try {
    const abandonedSessions = await db.collection("users")
      .where("currentlyInRanked", "==", true)
      .where("rankedSessionStartedAt", "<=", sixtyMinutesAgo)
      .get();

    if (abandonedSessions.empty) {
      return;
    }

    const batch = db.batch();

    abandonedSessions.docs.forEach((doc) => {
      const userData = doc.data();
      const currentReputation = userData.reputation ?? 0;
      const newReputation = onRankedAbandoned(currentReputation);

      batch.update(doc.ref, {
        currentlyInRanked: false,
        rankedSessionStartedAt: FieldValue.delete(),
        reputation: newReputation,
      });

      console.log(`Cleaned up abandoned ranked session for user: ${doc.id}. Reputation reduced from ${currentReputation} to ${newReputation}`);
    });

    await batch.commit();
  } catch (error) {
    console.error("Error in rankedSessionCleaner:", error);
  }
});

