export type LeagueName = "SCRIBE" | "STYLIST" | "AUTHOR" | "NOVELIST" | "LAUREATE" | "LUMINARY";

export const LEAGUES: { name: LeagueName; minRating: number }[] = [
  {name: "SCRIBE", minRating: 0},
  {name: "STYLIST", minRating: 30},
  {name: "AUTHOR", minRating: 60},
  {name: "NOVELIST", minRating: 90},
  {name: "LAUREATE", minRating: 120},
  {name: "LUMINARY", minRating: 150},
];

export function getLeagueFromRating(rating: number): LeagueName {
  const sortedLeagues = [...LEAGUES].sort((a, b) => b.minRating - a.minRating);
  for (const league of sortedLeagues) {
    if (rating >= league.minRating) {
      return league.name;
    }
  }
  return "SCRIBE";
}

functions/src/utils/reputationManager.ts.before_text:
export function adjustReputation(current: number, delta: number): number {
  const MAX = 1000;
  const MIN = -1000;

  const raw = current + delta;

  let clamped = raw;
  if (raw > MAX) clamped = MAX;
  if (raw < MIN) clamped = MIN;

  if (current !== 0 && clamped === 0) {
    return delta > 0 ? 1 : -1;
  }

  return clamped;
}

export function onRankedCompleted(current: number): number {
  return adjustReputation(current, 3);
}

export function onRankedAbandoned(current: number): number {
  return adjustReputation(current, -12);
}

functions/src/utils/tournamentRewards.ts.before_text:
/**
 * Calculates tournament reward percentages for each leaderboard position.
 * Top 80% of participants receive rewards, with first place receiving 45%
 * and the remainder distributed by a decreasing power curve.
 *
 * @param {number} players - Total number of participants in the tournament.
 * @return {number[]} A list of reward percentages by placement.
 */
export function calculateRewardPercentages(players: number): number[] {
  if (players === 1) {
    return [1.0];
  }

  if (players <= 0) return [];

  const losersCount = Math.floor(players * 0.2);
  const winnersCount = players - losersCount;

  if (winnersCount <= 0) return Array(players).fill(0.0);

  const result = Array(players).fill(0.0);

  const top1Percent = 0.45;
  result[0] = top1Percent;

  if (winnersCount === 1) return result;

  const exponent = 1.4;
  const weights: number[] = [];

  for (let i = 2; i <= winnersCount; i++) {
    const weight = 1.0 / Math.pow(i, exponent);
    weights.push(weight);
  }

  const totalWeight = weights.reduce((sum, value) => sum + value, 0);
  const remainingPercent = 1.0 - top1Percent;

  for (let i = 0; i < weights.length; i++) {
    const normalized = (weights[i] / totalWeight) * remainingPercent;
    result[i + 1] = normalized;
  }

  return result;
}

